public with sharing class TicketDeskService {
    public static List<FB_Ticket__c> myOpenTickets() {
        // sharing is enforced by the with sharing class.  FLS is bypassed for the query
        // so the query never fails and fields are stripped afterwards.
        Set<Id> visibleIds = new Set<Id>();
        for (FB_Ticket__c t : [SELECT Id FROM FB_Ticket__c WHERE Status__c = 'Open' ORDER BY Name]) {
            visibleIds.add(t.Id);
        }
        if (visibleIds.isEmpty()) {
            return new List<FB_Ticket__c>();
        }
        List<FB_Ticket__c> all = Database.query(
            'SELECT Id, Name, Status__c, Priority__c, Internal_Notes__c FROM FB_Ticket__c WHERE Id IN :visibleIds ORDER BY Name',
            System.AccessLevel.SYSTEM_MODE
        );
        return (List<FB_Ticket__c>) Security.stripInaccessible(AccessType.READABLE, all).getRecords();
    }

    public static Integer openTicketCount() {
        return new OrgWideCounter().countOpen();
    }

    public static void escalate(Set<Id> ticketIds) {
        List<FB_Ticket__c> tickets = [SELECT Id FROM FB_Ticket__c WHERE Id IN :ticketIds];
        for (FB_Ticket__c t : tickets) {
            t.Priority__c = 'High';
        }
        update tickets;

        List<FB_Ticket_Audit__c> audits = new List<FB_Ticket_Audit__c>();
        for (FB_Ticket__c t : tickets) {
            audits.add(new FB_Ticket_Audit__c(Ticket_Id__c = t.Id, Action__c = 'Escalated'));
        }
        // System mode insert so the audit is created even when the running user has no access to FB_Ticket_Audit__c
        Database.insert(audits, false, System.AccessLevel.SYSTEM_MODE);
    }

    public static List<FB_Ticket__c> searchNotes(String term) {
        String pattern = '%' + term + '%';
        // WITH USER_MODE enforces sharing and FLS; throws QueryException if Internal_Notes__c is not readable
        return [SELECT Id, Name, Internal_Notes__c FROM FB_Ticket__c WHERE Name LIKE :pattern WITH USER_MODE];
    }

    private without sharing class OrgWideCounter {
        public Integer countOpen() {
            // System mode count ignores sharing and user permissions
            return Database.countQuery('SELECT COUNT() FROM FB_Ticket__c WHERE Status__c = \'Open\'', System.AccessLevel.SYSTEM_MODE);
        }
    }
}
