public class ContactTriggerHandler {
    public static void handle(Boolean isBefore, Boolean isAfter, Boolean isInsert, Boolean isUpdate, List<Contact> newList, Map<Id, Contact> oldMap) {
        if (isBefore) {
            handleBefore(newList, isInsert);
        }
        if (isAfter && isInsert) {
            handleAfterInsert(newList);
        }
    }

    private static void handleBefore(List<Contact> contacts, Boolean isInsert) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accMap = new Map<Id, Account>([
            SELECT Id, BillingCountry, AccountSource
            FROM Account
            WHERE Id IN :accountIds
        ]);

        for (Contact c : contacts) {
            if (c.AccountId == null) {
                continue;
            }
            Account a = accMap.get(c.AccountId);
            if (a == null) {
                continue;
            }
            if (String.isBlank(c.MailingCountry)) {
                c.MailingCountry = a.BillingCountry;
            }
            if (isInsert && String.isBlank(c.LeadSource)) {
                c.LeadSource = a.AccountSource;
            }
        }
    }

    private static void handleAfterInsert(List<Contact> contacts) {
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : contacts) {
            if (c.AccountId != null && String.isNotBlank(c.Phone)) {
                accountIds.add(c.AccountId);
            }
        }
        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accMap = new Map<Id, Account>([
            SELECT Id, Phone
            FROM Account
            WHERE Id IN :accountIds
        ]);

        Map<Id, Contact> firstContactPerAccount = new Map<Id, Contact>();
        for (Contact c : contacts) {
            if (c.AccountId == null || String.isBlank(c.Phone)) {
                continue;
            }
            if (!firstContactPerAccount.containsKey(c.AccountId)) {
                firstContactPerAccount.put(c.AccountId, c);
            }
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accId : firstContactPerAccount.keySet()) {
            Account a = accMap.get(accId);
            if (a == null) {
                continue;
            }
            Contact c = firstContactPerAccount.get(accId);
            if (String.isBlank(a.Phone)) {
                a.Phone = c.Phone;
                accountsToUpdate.add(a);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
