public with sharing class ContactDomainService {

    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> grouped = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return grouped;
        }

        List<Contact> contacts = [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :accountIds
            AND Email != null
            WITH USER_MODE
        ];

        for (Contact c : contacts) {
            String email = c.Email;
            if (String.isBlank(email)) {
                continue;
            }

            Integer atIdx = email.lastIndexOf('@');
            if (atIdx <= 0 || atIdx >= email.length() - 1) {
                continue;
            }

            String domain = email.substring(atIdx + 1).trim().toLowerCase();

            if (!grouped.containsKey(domain)) {
                grouped.put(domain, new List<Contact>());
            }
            grouped.get(domain).add(c);
        }

        return grouped;
    }
}
