public with sharing class ContactLookupAction {

    @InvocableMethod(label='Find Contact by Email')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null) {
            return results;
        }

        // Preserve order and group indices by normalized email
        Map<String, List<Integer>> emailToIndices = new Map<String, List<Integer>>();
        Set<String> distinctEmails = new Set<String>();

        for (Integer i = 0; i < requests.size(); i++) {
            Request req = requests[i];
            Result res = new Result();
            res.found = false;
            res.contactId = null;
            results.add(res);

            String norm = normalizeEmail(req.email);
            if (String.isBlank(norm)) {
                continue;
            }

            if (!emailToIndices.containsKey(norm)) {
                emailToIndices.put(norm, new List<Integer>());
                distinctEmails.add(norm);
            }
            emailToIndices.get(norm).add(i);
        }

        Map<String, Contact> bestContactByEmail = new Map<String, Contact>();
        if (!distinctEmails.isEmpty()) {
            // Single SOQL query, sharing enforced by with sharing
            List<Contact> contacts = [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :distinctEmails
            ];

            for (Contact c : contacts) {
                if (String.isBlank(c.Email)) {
                    continue;
                }
                String normContactEmail = normalizeEmail(c.Email);
                if (!distinctEmails.contains(normContactEmail)) {
                    continue;
                }
                Contact existing = bestContactByEmail.get(normContactEmail);
                if (existing == null || c.CreatedDate < existing.CreatedDate) {
                    bestContactByEmail.put(normContactEmail, c);
                }
            }
        }

        for (String normEmail : emailToIndices.keySet()) {
            Contact best = bestContactByEmail.get(normEmail);
            for (Integer idx : emailToIndices.get(normEmail)) {
                Result res = results[idx];
                if (best != null) {
                    res.found = true;
                    res.contactId = best.Id;
                } else {
                    res.found = false;
                    res.contactId = null;
                }
            }
        }

        return results;
    }

    private static String normalizeEmail(String email) {
        if (email == null) {
            return null;
        }
        String trimmed = email.trim();
        if (trimmed == '') {
            return null;
        }
        return trimmed.toLowerCase();
    }

    public class Request {
        @InvocableVariable(required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable
        public Id contactId;

        @InvocableVariable
        public Boolean found;
    }
}
