public class OrderPayloadParser {

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public class PayloadException extends Exception {}

    private static Decimal toDecimal(Object o) {
        if (o == null) return null;
        if (o instanceof Decimal) return (Decimal) o;
        if (o instanceof Integer) return Decimal.valueOf((Integer) o);
        if (o instanceof Long) return Decimal.valueOf((Long) o);
        return Decimal.valueOf(String.valueOf(o));
    }

    private static Integer toInteger(Object o) {
        if (o == null) return null;
        if (o instanceof Integer) return (Integer) o;
        if (o instanceof Decimal) return ((Decimal) o).intValue();
        if (o instanceof Long) return ((Long) o).intValue();
        return Integer.valueOf(String.valueOf(o));
    }

    public static Order parse(String body) {
        try {
            if (String.isBlank(body)) {
                throw new PayloadException('Body is null or blank');
            }

            Object parsed;
            try {
                parsed = JSON.deserializeUntyped(body);
            } catch (Exception e) {
                throw new PayloadException('Invalid JSON');
            }

            if (!(parsed instanceof Map<String, Object>)) {
                throw new PayloadException('Not a JSON object');
            }

            Map<String, Object> root = (Map<String, Object>) parsed;

            Object numberObj = root.get('number');
            if (!(numberObj instanceof String) || String.isBlank((String) numberObj)) {
                throw new PayloadException('Missing or blank number');
            }
            String orderNumber = ((String) numberObj).trim();

            Date orderDate = null;
            Object dateObj = root.get('date');
            if (dateObj instanceof String) {
                try {
                    orderDate = Date.valueOf((String) dateObj);
                } catch (Exception e) {
                    // keep null if invalid
                }
            }

            String currencyCode = null;
            Object curObj = root.get('currency');
            if (curObj instanceof String) {
                currencyCode = (String) curObj;
            }

            String customerEmail = null;
            Object custObj = root.get('customer');
            if (custObj instanceof Map<String, Object>) {
                Object emailObj = ((Map<String, Object>) custObj).get('email');
                if (emailObj instanceof String) {
                    customerEmail = (String) emailObj;
                }
            }

            List<Line> lines = new List<Line>();
            Object linesObj = root.get('lines');
            if (linesObj instanceof List<Object>) {
                List<Object> linesList = (List<Object>) linesObj;
                for (Object item : linesList) {
                    if (!(item instanceof Map<String, Object>)) {
                        continue;
                    }
                    Map<String, Object> lineMap = (Map<String, Object>) item;

                    Object skuObj = lineMap.get('sku');
                    if (!(skuObj instanceof String) || String.isBlank((String) skuObj)) {
                        throw new PayloadException('Missing sku');
                    }
                    String sku = (String) skuObj;

                    Object qtyObj = lineMap.get('quantity');
                    if (qtyObj == null) {
                        throw new PayloadException('Missing quantity');
                    }
                    Integer quantity = toInteger(qtyObj);
                    if (quantity == null || quantity <= 0) {
                        throw new PayloadException('Invalid quantity');
                    }

                    Object upObj = lineMap.get('unitPrice');
                    if (upObj == null) {
                        throw new PayloadException('Missing unitPrice');
                    }
                    Decimal unitPrice = toDecimal(upObj);
                    if (unitPrice == null || unitPrice < 0) {
                        throw new PayloadException('Invalid unitPrice');
                    }

                    Decimal discount = 0;
                    if (lineMap.containsKey('discount')) {
                        Object dObj = lineMap.get('discount');
                        if (dObj != null) {
                            discount = toDecimal(dObj);
                            if (discount == null) discount = 0;
                        }
                    }

                    Decimal raw = Decimal.valueOf(quantity) * unitPrice * (1 - discount);
                    Decimal lineTotal = raw.setScale(2, RoundingMode.HALF_UP);

                    Line ln = new Line();
                    ln.sku = sku;
                    ln.quantity = quantity;
                    ln.unitPrice = unitPrice;
                    ln.discount = discount;
                    ln.lineTotal = lineTotal;
                    lines.add(ln);
                }
            }

            Decimal total = 0;
            for (Line ln : lines) {
                total += ln.lineTotal;
            }

            Order order = new Order();
            order.orderNumber = orderNumber;
            order.orderDate = orderDate;
            order.currencyCode = currencyCode;
            order.customerEmail = customerEmail;
            order.lines = lines;
            order.total = total;
            return order;
        } catch (PayloadException pe) {
            throw pe;
        } catch (Exception e) {
            throw new PayloadException(e.getMessage());
        }
    }

    public static String toAcknowledgement(Order order) {
        Map<String, Object> ack = new Map<String, Object>();
        ack.put('number', order != null && order.orderNumber != null ? order.orderNumber : null);
        ack.put('status', 'RECEIVED');
        Integer lineCount = (order != null && order.lines != null) ? order.lines.size() : 0;
        ack.put('lineCount', lineCount);
        Decimal total = (order != null && order.total != null) ? order.total : 0;
        ack.put('total', total);
        return JSON.serialize(ack);
    }
}
