public with sharing class LeadImportService {

    public class ImportResult {
        public Integer successCount;
        public List<Id> insertedIds;
        public Map<Integer, String> errorsByIndex;

        public ImportResult() {
            this.successCount = 0;
            this.insertedIds = new List<Id>();
            this.errorsByIndex = new Map<Integer, String>();
        }
    }

    public static ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        Set<String> seenEmails = new Set<String>();
        List<Lead> leadsToInsert = new List<Lead>();
        List<Integer> originalIndices = new List<Integer>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead ld = leads[i];
            if (ld == null) {
                result.errorsByIndex.put(i, 'Lead is null');
                continue;
            }

            if (ld.LeadSource == null || ld.LeadSource.trim() == '') {
                ld.LeadSource = 'Web';
            }

            String email = ld.Email;
            if (email != null) {
                String trimmedEmail = email.trim();
                if (trimmedEmail != '') {
                    String norm = trimmedEmail.toLowerCase();
                    if (seenEmails.contains(norm)) {
                        result.errorsByIndex.put(i, 'Duplicate email in import: ' + norm);
                        continue;
                    } else {
                        seenEmails.add(norm);
                    }
                }
            }

            leadsToInsert.add(ld);
            originalIndices.add(i);
        }

        if (leadsToInsert.isEmpty()) {
            return result;
        }

        Database.SaveResult[] saveResults = Database.insert(leadsToInsert, false);

        for (Integer j = 0; j < saveResults.size(); j++) {
            Database.SaveResult sr = saveResults[j];
            Integer origIdx = originalIndices[j];

            if (sr.isSuccess()) {
                result.successCount++;
                result.insertedIds.add(sr.getId());
            } else {
                List<String> msgs = new List<String>();
                for (Database.Error err : sr.getErrors()) {
                    msgs.add(err.getMessage());
                }
                String msg = String.join(msgs, '; ');
                result.errorsByIndex.put(origIdx, msg);
            }
        }

        return result;
    }
}
