public class ShipmentEventHandler {
    public static void handle(List<FB_Shipment_Event__e> events) {
        if (events == null || events.isEmpty()) {
            return;
        }

        Map<String, FB_Shipment_Event__e> latestByOrder = new Map<String, FB_Shipment_Event__e>();
        Set<String> orderNums = new Set<String>();

        for (FB_Shipment_Event__e e : events) {
            if (String.isBlank(e.Order_Number__c)) {
                continue;
            }
            String key = e.Order_Number__c.toUpperCase();
            latestByOrder.put(key, e);
            orderNums.add(key);
        }

        if (orderNums.isEmpty()) {
            return;
        }

        Map<String, FB_Sales_Order__c> orderMap = new Map<String, FB_Sales_Order__c>();
        for (FB_Sales_Order__c o : [
            SELECT Id, Order_Number__c, Status__c, Tracking_Number__c, Carrier__c, Shipped_Date__c
            FROM FB_Sales_Order__c
            WHERE Order_Number__c IN :orderNums
        ]) {
            orderMap.put(o.Order_Number__c, o);
        }

        List<FB_Sales_Order__c> toUpdate = new List<FB_Sales_Order__c>();
        for (String key : latestByOrder.keySet()) {
            FB_Sales_Order__c order = orderMap.get(key);
            if (order == null) {
                continue;
            }
            if (order.Status__c == 'Cancelled') {
                continue;
            }

            FB_Shipment_Event__e e = latestByOrder.get(key);
            order.Status__c = 'Shipped';
            order.Tracking_Number__c = e.Tracking_Number__c;
            order.Carrier__c = e.Carrier__c;
            order.Shipped_Date__c = Date.today();
            toUpdate.add(order);
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
