public class OpportunityPipelineHandler {
    public static void onAfterInsert(List<Opportunity> newOpps) {
        Set<Id> accountIds = getAccountIdsFromOpps(newOpps, true);
        updateAccounts(accountIds);
    }

    public static void onAfterUndelete(List<Opportunity> newOpps) {
        Set<Id> accountIds = getAccountIdsFromOpps(newOpps, true);
        updateAccounts(accountIds);
    }

    public static void onAfterDelete(List<Opportunity> oldOpps) {
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity o : oldOpps) {
            if (o.AccountId != null && !o.IsClosed) {
                accountIds.add(o.AccountId);
            }
        }
        updateAccounts(accountIds);
    }

    public static void onAfterUpdate(Map<Id, Opportunity> newMap, Map<Id, Opportunity> oldMap) {
        Set<Id> accountIds = new Set<Id>();
        for (Id oppId : newMap.keySet()) {
            Opportunity newOpp = newMap.get(oppId);
            Opportunity oldOpp = oldMap.get(oppId);

            Boolean accountChanged = newOpp.AccountId != oldOpp.AccountId;
            Boolean isClosedChanged = newOpp.IsClosed != oldOpp.IsClosed;
            Boolean amountChanged = newOpp.Amount != oldOpp.Amount;

            if (accountChanged || isClosedChanged || amountChanged) {
                if (oldOpp.AccountId != null) {
                    accountIds.add(oldOpp.AccountId);
                }
                if (newOpp.AccountId != null) {
                    accountIds.add(newOpp.AccountId);
                }
            }
        }
        if (!accountIds.isEmpty()) {
            updateAccounts(accountIds);
        }
    }

    private static Set<Id> getAccountIdsFromOpps(List<Opportunity> opps, Boolean onlyOpen) {
        Set<Id> ids = new Set<Id>();
        if (opps == null) return ids;
        for (Opportunity o : opps) {
            if (o.AccountId != null) {
                if (!onlyOpen || !o.IsClosed) {
                    ids.add(o.AccountId);
                }
            }
        }
        return ids;
    }

    private static void updateAccounts(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        List<AggregateResult> agg = [
            SELECT AccountId, COUNT(Id) oppCount, SUM(Amount) totalAmt
            FROM Opportunity
            WHERE AccountId IN :accountIds AND IsClosed = false
            GROUP BY AccountId
        ];

        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();
        for (Id accId : accountIds) {
            accountsToUpdate.put(accId, new Account(
                Id = accId,
                FB_Open_Pipeline__c = 0,
                FB_Open_Opportunities__c = 0
            ));
        }

        for (AggregateResult ar : agg) {
            Id accId = (Id) ar.get('AccountId');
            Integer cnt = (Integer) ar.get('oppCount');
            Decimal sum = (Decimal) ar.get('totalAmt');
            if (sum == null) {
                sum = 0;
            }
            Account acc = accountsToUpdate.get(accId);
            if (acc != null) {
                acc.FB_Open_Pipeline__c = sum;
                acc.FB_Open_Opportunities__c = cnt;
            }
        }

        update accountsToUpdate.values();
    }
}
