public class LogPurgeJob implements Schedulable {

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext ctx) {
        DateTime thirtyDaysAgo = System.now().addDays(-30);
        DateTime oneEightyDaysAgo = System.now().addDays(-180);

        List<FB_Integration_Log__c> batch;
        do {
            batch = [
                SELECT Id
                FROM FB_Integration_Log__c
                WHERE (
                    CreatedDate < :thirtyDaysAgo
                    AND (Level__c != 'ERROR' OR Level__c = null)
                )
                OR (
                    CreatedDate < :oneEightyDaysAgo
                    AND Level__c = 'ERROR'
                )
                LIMIT 10000
            ];
            if (!batch.isEmpty()) {
                delete batch;
            }
        } while (batch.size() == 10000);
    }

    public static Id scheduleNightly() {
        String cronExpression = '0 0 2 * * ?'; // daily at 02:00
        return System.schedule('Log purge (nightly)', cronExpression, new LogPurgeJob());
    }
}
