public with sharing class OpportunityRollupService {

    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new Map<Id, Decimal>();
        }

        Integer yr = Date.today().year();
        Date startDate = Date.newInstance(yr, 1, 1);
        Date endDate = Date.newInstance(yr, 12, 31);

        Map<Id, Decimal> result = new Map<Id, Decimal>();
        for (Id accId : accountIds) {
            result.put(accId, 0);
        }

        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) total
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsWon = TRUE
              AND CloseDate >= :startDate
              AND CloseDate <= :endDate
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('AccountId');
            Decimal total = (Decimal) ar.get('total');
            result.put(accId, total == null ? 0 : total);
        }

        return result;
    }
}
