        public fflib_SObjectDomain construct(List<SObject> sObjects) {
            return new Opportunities((List<Opportunity>) sObjects);
        }
    }

    protected override void onBeforeInsert() {
        validateAmountNotNegative();
    }

    protected override void onBeforeUpdate() {
        validateAmountNotNegative();
        validateAmountUnchangedOnWon();
    }

    private void validateAmountNotNegative() {
        for (Opportunity opp : (List<Opportunity>) Records) {
            if (opp.Amount != null && opp.Amount < 0) {
                this.addError('Amount cannot be negative.', opp, Opportunity.Amount);
            }
        }
    }

    private void validateAmountUnchangedOnWon() {
        for (Opportunity opp : (List<Opportunity>) Records) {
            Opportunity oldOpp = (Opportunity) getOldRecord(opp.Id);
            if (oldOpp == null) {
                continue;
            }
            if (oldOpp.StageName == 'Closed Won') {
                if (oldOpp.Amount != opp.Amount) {
                    this.addError('Amount cannot change on a won opportunity.', opp, Opportunity.Amount);
                }
            }
        }
    }
}
