public class CaseEscalationService {
    public class EscalationException extends Exception {}

    public static void escalate(Set<Id> caseIds, String reason) {
        if (String.isBlank(reason)) {
            throw new EscalationException('Reason is required');
        }

        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = CasesSelector.newInstance().selectById(caseIds);
        if (cases == null) {
            cases = new List<Case>();
        }

        fflib_SObjectUnitOfWork uow = null;
        Boolean hasWork = false;

        for (Case c : cases) {
            if (c.Status == 'Closed' || c.IsEscalated == true) {
                continue;
            }

            c.IsEscalated = true;
            c.Priority = 'High';

            Task t = new Task();
            t.Subject = 'Escalated: ' + reason;
            t.WhatId = c.Id;
            t.OwnerId = c.OwnerId;
            t.ActivityDate = Date.today().addDays(1);
            t.Priority = 'High';

            if (uow == null) {
                uow = Application.UnitOfWork.newInstance();
            }
            uow.registerDirty(c);
            uow.registerNew(t);
            hasWork = true;
        }

        if (hasWork && uow != null) {
            uow.commitWork();
        }
    }
}
