public class OpportunityWinService {
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opps = OpportunitiesSelector.newInstance().selectById(opportunityIds);
        if (opps == null || opps.isEmpty()) {
            return 0;
        }

        fflib_Application.UnitOfWork uow = Application.UnitOfWork.newInstance();
        Integer closedCount = 0;
        Date today = Date.today();

        for (Opportunity opp : opps) {
            if (opp.StageName == 'Closed Won') {
                continue;
            }

            opp.StageName = 'Closed Won';
            opp.CloseDate = today;
            uow.registerDirty(opp);

            Deal_Won__e evt = new Deal_Won__e();
            evt.Opportunity_Id__c = String.valueOf(opp.Id);
            evt.Amount__c = opp.Amount;
            uow.registerNew(evt);

            closedCount++;
        }

        if (closedCount > 0) {
            uow.commitWork();
        }

        return closedCount;
    }
}
