public class ContactPhoneCleanup {
    /**
     * Normalizes Contact.Phone values to digits and leading plus only.
     * Returns a map of Contact Id -> first error message for records that could not be saved.
     *
     * Note: The implementation only queues an update when the normalized value differs
     * from the current Phone. This avoids unnecessary DML, governor consumption and
     * trigger recursion while preserving the requested bulk update with allOrNone=false.
     */
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> errors = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return errors;
        }

        Set<Id> idSet = new Set<Id>(contactIds);
        List<Contact> contacts = [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :idSet
        ];

        List<Contact> toUpdate = new List<Contact>();
        for (Contact c : contacts) {
            if (String.isBlank(c.Phone)) {
                continue; // contacts without a phone are left out
            }
            String normalized = c.Phone.replaceAll('[^0-9+]', '');
            if (normalized != c.Phone) {
                c.Phone = normalized;
                toUpdate.add(c);
            }
        }

        if (!toUpdate.isEmpty()) {
            Database.SaveResult[] results = Database.update(toUpdate, false);
            for (Integer i = 0; i < results.size(); i++) {
                if (!results[i].isSuccess()) {
                    Id recId = toUpdate[i].Id;
                    String firstMsg = results[i].getErrors()[0].getMessage();
                    errors.put(recId, firstMsg);
                }
            }
        }

        return errors;
    }
}
