public class PipelineSummary {
    // Note on design: In a real org I would run a single aggregate query with
    // GROUP BY StageName to avoid multiple SOQL statements and governor limits.
    // The requirement here explicitly asks for one query per stage for readability,
    // which is acceptable because the stage list is fixed at four items.

    private static final List<String> STAGES = new List<String>{
        'Prospecting',
        'Qualification',
        'Proposal/Price Quote',
        'Negotiation/Review'
    };

    public static Map<String, Decimal> totalsByStage(Date fromDate, Date toDate) {
        Map<String, Decimal> totals = new Map<String, Decimal>();

        for (String stage : STAGES) {
            Decimal sum = 0;
            AggregateResult ar = [
                SELECT SUM(Amount) sumAmt
                FROM Opportunity
                WHERE StageName = :stage
                AND CloseDate >= :fromDate
                AND CloseDate <= :toDate
            ];
            if (ar != null) {
                Decimal s = (Decimal) ar.get('sumAmt');
                sum = s == null ? 0 : s;
            }
            totals.put(stage, sum);
        }

        return totals;
    }
}
