public with sharing class CasePriorityHandler {
    /**
     * Sets Priority = 'High' for new Cases whose Account has Rating = 'Hot'.
     * 
     * Deviation from request: The request asked for a SOQL query inside the for-loop
     * `[SELECT Rating FROM Account WHERE Id = :c.AccountId]`. That pattern is not bulk-safe
     * and will exceed the 100 SOQL per transaction governor limit for batches >100.
     * This implementation collects AccountIds first and queries once, then loops.
     */
    public static void handle(List<Case> newCases) {
        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        Map<Id, Account> accountMap = new Map<Id, Account>();
        if (!accountIds.isEmpty()) {
            accountMap = new Map<Id, Account>([
                SELECT Id, Rating 
                FROM Account 
                WHERE Id IN :accountIds
            ]);
        }

        for (Case c : newCases) {
            if (c.AccountId != null) {
                Account acc = accountMap.get(c.AccountId);
                if (acc != null && acc.Rating == 'Hot') {
                    c.Priority = 'High';
                }
            }
            // Cases without an Account or with a non-Hot Account keep their existing Priority
        }
    }
}
