public class ErpCustomerSync {

    // One Queueable per Account => one HTTP request per Account
    public class SyncJob implements Queueable, Database.AllowsCallouts {
        private final Account acc;

        public SyncJob(Account acc) {
            this.acc = acc;
        }

        public void execute(QueueableContext ctx) {
            Http http = new Http();
            HttpRequest req = new HttpRequest();
            req.setEndpoint('callout:ERP/api/customers');
            req.setMethod('POST');
            req.setHeader('Content-Type', 'application/json');

            String salesforceId = acc.Id; // 18-character Id in API v59+
            String name = acc.Name;
            String country = String.isBlank(acc.BillingCountry) ? null : acc.BillingCountry;

            Map<String, Object> item = new Map<String, Object>{
                'salesforceId' => salesforceId,
                'name'         => name,
                'country'      => country
            };
            // ERP expects a JSON array with 1 to 200 customers
            String body = JSON.serialize(new List<Object>{ item });
            req.setBody(body);

            // Error handling / retries are out of scope for this ticket
            HttpResponse res = http.send(req);
        }
    }

    public static void enqueueForAccounts(List<Account> accounts) {
        // One job per account to keep ERP traceability per account
        for (Account a : accounts) {
            System.enqueueJob(new SyncJob(a));
        }
    }
}
