public class DealEventPublisher {
    /**
     * Publishes one Deal_Stage_Change__e event per Opportunity in the input list.
     * Results are returned in the same order as the input opportunities.
     * An empty or null input returns an empty list and publishes nothing.
     *
     * No deviation from the requested per-opportunity publish pattern is made:
     * EventBus.publish is invoked once per opportunity inside the loop so the
     * SaveResult can be mapped directly to the originating Opportunity. With a
     * maximum of 200 records from the trigger handler this stays well within
     * platform event governor limits.
     */
    public static List<Database.SaveResult> publishStageChanges(List<Opportunity> opportunities) {
        List<Database.SaveResult> results = new List<Database.SaveResult>();

        if (opportunities == null || opportunities.isEmpty()) {
            return results;
        }

        for (Opportunity opp : opportunities) {
            // Defensive guard – trigger handler should only pass valid records
            if (opp == null || opp.Id == null) {
                continue;
            }

            Deal_Stage_Change__e evt = new Deal_Stage_Change__e(
                Opportunity_Id__c = opp.Id,      // 18-character Id
                Stage__c         = opp.StageName,
                Amount__c        = opp.Amount
            );

            Database.SaveResult sr = EventBus.publish(evt);
            results.add(sr);
        }

        return results;
    }
}
