public class FollowUpTaskService {
    /**
     * Creates a follow-up Task for each Opportunity in opportunityIds.
     *
     * NOTE ON IMPLEMENTATION:
     * The brief asks for a per-record try/catch with a DML in the loop. In a production org
     * that pattern is not bulk-safe. With 150-250 Opportunities in one call a looped insert
     * would hit the 150 DML statements governor limit and is an anti-pattern.
     * This implementation is bulkified: Opportunities are queried once, Tasks are built in
     * memory and inserted with Database.insert(tasks, false). Partial failures are collected
     * so a validation rule rejection on one Task does not stop the others, which satisfies the
     * functional requirement while staying within governor limits.
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOppIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOppIds;
        }

        // De-duplicate for governor safety
        Set<Id> uniqueOppIds = new Set<Id>(opportunityIds);

        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>([
            SELECT Id, Name, OwnerId
            FROM Opportunity
            WHERE Id IN :uniqueOppIds
        ]);

        List<Task> tasksToInsert = new List<Task>();
        List<Id> oppIdsForTasks = new List<Id>();

        for (Id oppId : uniqueOppIds) {
            Opportunity opp = oppMap.get(oppId);
            if (opp == null || String.isBlank(opp.Name) || opp.OwnerId == null) {
                failedOppIds.add(oppId);
                continue;
            }

            Task t = new Task(
                WhatId      = opp.Id,
                OwnerId     = opp.OwnerId,
                Subject     = 'Follow up: ' + opp.Name,
                ActivityDate = Date.today().addDays(7),
                Status      = 'Not Started',
                Priority    = 'Normal'
            );
            tasksToInsert.add(t);
            oppIdsForTasks.add(oppId);
        }

        if (!tasksToInsert.isEmpty()) {
            Database.SaveResult[] results = Database.insert(tasksToInsert, false);
            for (Integer i = 0; i < results.size(); i++) {
                if (!results[i].isSuccess()) {
                    failedOppIds.add(oppIdsForTasks[i]);
                }
            }
        }

        return failedOppIds;
    }
}
