public with sharing class LeadContactMatcher {
    public static List<Id> matchByEmail(List<Lead> leads, List<Contact> contacts) {
        if (leads == null) {
            return new List<Id>();
        }
        if (contacts == null) {
            contacts = new List<Contact>();
        }

        List<Id> result = new List<Id>(leads.size());

        for (Lead lead : leads) {
            String leadEmail = lead != null ? lead.Email : null;
            if (String.isBlank(leadEmail)) {
                result.add(null);
                continue;
            }
            String normLeadEmail = leadEmail.trim().toLowerCase();

            Id matchedContactId = null;
            for (Contact con : contacts) {
                String contactEmail = con != null ? con.Email : null;
                if (String.isBlank(contactEmail)) {
                    continue;
                }
                if (contactEmail.trim().toLowerCase() == normLeadEmail) {
                    matchedContactId = con.Id;
                    break; // first match in contacts order wins
                }
            }
            result.add(matchedContactId);
        }
        return result;
    }
}
