public class RenewalReminderService {

    /*
     * NOTE ON THE REQUESTED APPROACH
     * Sending one Messaging.sendEmail per opportunity in a loop is an anti-pattern.
     * It wastes CPU / heap, adds call overhead, and makes it easy to hit the
     * per-transaction email limit of 100 messages and the daily org limits.
     * With up to 200 ids per call you will exceed the limit and the transaction
     * will fail part-way through. The correct bulk pattern is to build all
     * SingleEmailMessage instances and send them in one Messaging.sendEmail call,
     * then inspect the SendEmailResult[] for individual failures.
     * The implementation below follows the literal requirement to call sendEmail
     * inside the loop so individual failures do not block the rest.
     */

    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Bulk query once
        List<Opportunity> opps = [
            SELECT Id, Name, CloseDate, OwnerId
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ];

        Integer sentCount = 0;

        for (Opportunity opp : opps) {
            if (opp.OwnerId == null) {
                continue;
            }

            // Owner must be a User for setTargetObjectId to work reliably
            // 005 is the User prefix
            if (!String.valueOf(opp.OwnerId).startsWith('005')) {
                continue;
            }

            Messaging.SingleEmailMessage mail = new Messaging.SingleEmailMessage();
            mail.setTargetObjectId(opp.OwnerId);
            mail.setTreatTargetObjectAsRecipient(true);
            mail.setSaveAsActivity(false);
            mail.setSubject('Renewal due: ' + opp.Name);

            String closeDateText = opp.CloseDate != null ? String.valueOf(opp.CloseDate) : 'unknown date';
            String body = 'Hello,\n\n'
                + 'The opportunity "' + opp.Name + '" has a renewal due on ' + closeDateText + '.\n'
                + 'Please review the record and take the required action.\n\n'
                + 'Thanks';
            mail.setPlainTextBody(body);

            // One sendEmail per opportunity per requirement
            try {
                Messaging.SendEmailResult[] results = Messaging.sendEmail(new Messaging.SingleEmailMessage[] { mail });
                if (results != null && results.size() > 0 && results[0].isSuccess()) {
                    sentCount++;
                }
            } catch (Exception e) {
                // Log in real implementation; continue with next opportunity
                continue;
            }
        }

        return sentCount;
    }
}
