import { LightningElement, api } from 'lwc';

export default class AccountContactList extends LightningElement {
    @api contacts;

    get hasContacts() {
        return Array.isArray(this.contacts) && this.contacts.length > 0;
    }

    get sortedContacts() {
        if (!this.hasContacts) {
            return [];
        }
        // Create a shallow copy to avoid mutating the parent-owned array
        return [...this.contacts].sort((a, b) => {
            const nameA = a?.Name ?? '';
            const nameB = b?.Name ?? '';
            return nameA.localeCompare(nameB);
        });
    }

    get contactCountText() {
        const len = this.contacts?.length ?? 0;
        return `${len} contact${len === 1 ? '' : 's'}`;
    }
}
