import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    @api lines = [];

    error = false;

    handleClick(event) {
        const action = event.currentTarget.dataset.action;
        if (action === 'reset') {
            this.handleReset();
        } else if (action === 'submit') {
            this.handleSubmit();
        }
    }

    handleReset() {
        const editors = this.template.querySelectorAll('c-line-item-editor');
        editors.forEach(editor => editor.reset());
        this.error = false;
    }

    handleSubmit() {
        const editors = this.template.querySelectorAll('c-line-item-editor');
        let allValid = true;

        editors.forEach(editor => {
            const valid = editor.validate();
            if (!valid) {
                allValid = false;
            }
        });

        if (allValid) {
            const lines = [];
            editors.forEach(editor => {
                lines.push(editor.getValue());
            });
            this.error = false;
            this.dispatchEvent(new CustomEvent('submit', {
                detail: { lines }
            }));
        } else {
            this.error = true;
        }
    }
}
