import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

export default class QueueMonitor extends LightningElement {
    waiting = null;
    longestWaitMinutes = null;
    error = null;

    _isLoading = false;
    _intervalId = null;
    _boundVisibilityChange = null;

    connectedCallback() {
        this._boundVisibilityChange = () => this._handleVisibilityChange();
        document.addEventListener('visibilitychange', this._boundVisibilityChange);

        if (document.visibilityState === 'visible') {
            this._startPolling();
            this.loadStats();
        }
    }

    disconnectedCallback() {
        this._stopPolling();
        if (this._boundVisibilityChange) {
            document.removeEventListener('visibilitychange', this._boundVisibilityChange);
        }
    }

    _handleVisibilityChange() {
        if (document.visibilityState === 'visible') {
            this._startPolling();
            this.loadStats();
        } else {
            this._stopPolling();
        }
    }

    _startPolling() {
        this._stopPolling();
        this._intervalId = setInterval(() => {
            this.loadStats();
        }, 60000);
    }

    _stopPolling() {
        if (this._intervalId) {
            clearInterval(this._intervalId);
            this._intervalId = null;
        }
    }

    async loadStats() {
        if (document.visibilityState !== 'visible') {
            return;
        }
        if (this._isLoading) {
            return;
        }
        this._isLoading = true;
        try {
            const result = await getQueueStats();
            this.waiting = result.waiting;
            this.longestWaitMinutes = result.longestWaitMinutes;
            this.error = null;
        } catch (err) {
            const message = err?.body?.message || err?.message || 'Unknown error';
            this.error = message;
        } finally {
            this._isLoading = false;
        }
    }

    get hasStats() {
        return this.waiting !== null && this.longestWaitMinutes !== null;
    }
}
