import { LightningElement } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import register from '@salesforce/apex/RegistrationController.register';

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleChange(event) {
        const field = event.target.dataset.field;
        const value = event.detail.value;
        if (field === 'fullName') {
            this.fullName = value;
        } else if (field === 'email') {
            this.email = value;
        } else if (field === 'company') {
            this.company = value;
        }
    }

    handleRegister() {
        const emailInput = this.template.querySelector('lightning-input[data-field="email"]');
        const inputs = this.template.querySelectorAll('lightning-input');

        // Step 1: work email validation
        const emailValue = (this.email || '').trim();
        let domain = '';
        if (emailValue.includes('@')) {
            domain = emailValue.substring(emailValue.lastIndexOf('@') + 1).toLowerCase();
        }
        const blocked = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'];
        if (emailValue && blocked.includes(domain)) {
            emailInput.setCustomValidity('Use your work email address.');
        } else {
            emailInput.setCustomValidity('');
        }

        // Step 2: report validity on every input
        let allValid = true;
        inputs.forEach(inp => {
            const valid = inp.reportValidity();
            if (!valid) {
                allValid = false;
            }
        });

        // Step 3: stop if invalid
        if (!allValid) {
            return;
        }

        // Step 3: call Apex
        register({
            fullName: this.fullName,
            email: this.email,
            company: this.company
        })
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registered',
                        variant: 'success'
                    })
                );
            })
            .catch(error => {
                const message = error.body && error.body.message ? error.body.message : error.message;
                this.dispatchEvent(
                    new ShowToastEvent({
                        title: 'Registration failed',
                        variant: 'error',
                        message
                    })
                );
            });
    }
}
