import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading;

    _tasks = [];
    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get tasks() {
        return this._tasks;
    }
    set tasks(value) {
        if (Array.isArray(value)) {
            this._tasks = value.map(t => ({ ...t }));
            this.items = this._tasks.map(t => ({ ...t }));
            let max = 0;
            this.items.forEach(t => {
                const m = t.id && t.id.toString().match(/(\d+)$/);
                if (m) {
                    const n = parseInt(m[1], 10);
                    if (n > max) max = n;
                }
            });
            this.nextId = max + 1;
        } else {
            this._tasks = [];
            this.items = [];
            this.nextId = 1;
        }
    }

    get displayHeading() {
        return this.heading ? this.heading.toUpperCase() : '';
    }

    get remaining() {
        return this.items.filter(t => !t.done).length;
    }

    connectedCallback() {
        if (this.items.length === 0 && this._tasks.length > 0) {
            this.items = this._tasks.map(t => ({ ...t }));
        }
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = (this.newLabel || '').trim();
        if (!label) {
            return;
        }
        const newTask = {
            id: `new-${this.nextId++}`,
            label,
            done: false
        };
        this.items = [...this.items, newTask];
        this.newLabel = '';
        this.dispatchEvent(new CustomEvent('taskadded', {
            detail: { label },
            bubbles: true,
            composed: true
        }));
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        if (!id) return;
        this.items = this.items.map(t => {
            if (t.id === id) {
                return { ...t, done: !t.done };
            }
            return t;
        });
    }
}
