public with sharing class EmployerService {
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = employerByContactId.keySet();

        // 1 SOQL
        Map<Id, Contact> contactsMap = new Map<Id, Contact>([
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :contactIds
        ]);

        List<Contact> contactsToUpdate = new List<Contact>();
        for (Id contactId : contactsMap.keySet()) {
            Id orgId = employerByContactId.get(contactId);
            if (orgId == null) {
                continue;
            }
            Contact c = contactsMap.get(contactId);
            if (c == null) {
                continue;
            }
            Id currentPrimary = c.npsp__Primary_Affiliation__c;
            if (currentPrimary == null || currentPrimary != orgId) {
                c.npsp__Primary_Affiliation__c = orgId;
                contactsToUpdate.add(c);
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            // 1 DML - NPSP will create/update the Current Primary Affiliation
            // and close the previous primary employer to Former with EndDate = today
            update contactsToUpdate;
        }
    }
}
