public class GauAllocationService {
    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        if (opportunityId == null) {
            throw new AllocationException('Opportunity Id is required');
        }
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('Percent map is null or empty');
        }

        Decimal totalPercent = 0;
        for (Decimal p : percentByGauId.values()) {
            if (p == null || p <= 0) {
                throw new AllocationException('Percent must be greater than zero');
            }
            totalPercent += p;
        }
        if (totalPercent > 100) {
            throw new AllocationException('Total percent cannot exceed 100');
        }

        Set<Id> gauIds = percentByGauId.keySet();
        Map<Id, npsp__General_Accounting_Unit__c> gauMap = new Map<Id, npsp__General_Accounting_Unit__c>([
            SELECT Id, npsp__Active__c
            FROM npsp__General_Accounting_Unit__c
            WHERE Id IN :gauIds
        ]);
        if (gauMap.size() != gauIds.size()) {
            throw new AllocationException('One or more GAUs not found');
        }
        for (Id gid : gauIds) {
            if (gauMap.get(gid).npsp__Active__c != true) {
                throw new AllocationException('GAU is inactive: ' + gid);
            }
        }

        Opportunity opp;
        try {
            opp = [SELECT Id, Amount FROM Opportunity WHERE Id = :opportunityId LIMIT 1];
        } catch (Exception e) {
            throw new AllocationException('Opportunity not found');
        }

        // Remove existing GAU allocations for this opportunity
        List<npsp__Allocation__c> existing = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
            AND npsp__General_Accounting_Unit__c != null
        ];
        if (!existing.isEmpty()) {
            delete existing;
        }

        List<npsp__Allocation__c> toInsert = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            Decimal pct = percentByGauId.get(gauId);
            npsp__Allocation__c alloc = new npsp__Allocation__c();
            alloc.npsp__Opportunity__c = opportunityId;
            alloc.npsp__General_Accounting_Unit__c = gauId;
            alloc.npsp__Percent__c = pct;
            if (opp.Amount != null) {
                alloc.npsp__Amount__c = opp.Amount * pct / 100;
            }
            toInsert.add(alloc);
        }

        insert toInsert;
        return toInsert;
    }
}
