public class PaymentPlanService {
    public class PaymentPlanException extends Exception {}

    public static List<npe01__OppPayment__c> scheduleInstallments(Id opportunityId, Integer numberOfPayments, Date firstPaymentDate) {
        if (opportunityId == null) {
            throw new PaymentPlanException('Opportunity Id is required');
        }
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('numberOfPayments must be greater than zero');
        }
        if (firstPaymentDate == null) {
            throw new PaymentPlanException('firstPaymentDate is required');
        }

        Opportunity opp = [
            SELECT Id, Amount, IsClosed
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
        ];

        if (opp.IsClosed) {
            throw new PaymentPlanException('Opportunity is closed');
        }

        List<npe01__OppPayment__c> payments = [
            SELECT Id, npe01__Payment_Amount__c, npe01__Paid__c, npe01__Written_Off__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
        ];

        Decimal paidWrittenOffSum = 0;
        List<npe01__OppPayment__c> toDelete = new List<npe01__OppPayment__c>();

        for (npe01__OppPayment__c p : payments) {
            Boolean isPaid = p.npe01__Paid__c == true;
            Boolean isWrittenOff = p.npe01__Written_Off__c == true;

            if (isPaid || isWrittenOff) {
                if (p.npe01__Payment_Amount__c != null) {
                    paidWrittenOffSum += p.npe01__Payment_Amount__c;
                }
            } else {
                toDelete.add(p);
            }
        }

        Decimal oppAmount = opp.Amount != null ? opp.Amount : 0;
        Decimal outstanding = oppAmount - paidWrittenOffSum;

        if (outstanding <= 0) {
            throw new PaymentPlanException('Outstanding amount must be greater than zero');
        }

        Savepoint sp = Database.setSavepoint();
        try {
            if (!toDelete.isEmpty()) {
                delete toDelete;
            }

            Decimal baseAmount = outstanding.divide(new Decimal(numberOfPayments), 2, RoundingMode.DOWN);
            // Ensure two decimal scale
            baseAmount = baseAmount.setScale(2, RoundingMode.DOWN);

            List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();

            for (Integer i = 0; i < numberOfPayments; i++) {
                Decimal amt;
                if (i == numberOfPayments - 1) {
                    Decimal sumPrev = baseAmount * (numberOfPayments - 1);
                    amt = outstanding - sumPrev;
                } else {
                    amt = baseAmount;
                }

                npe01__OppPayment__c p = new npe01__OppPayment__c(
                    npe01__Opportunity__c = opportunityId,
                    npe01__Payment_Amount__c = amt,
                    npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i),
                    npe01__Paid__c = false,
                    npe01__Written_Off__c = false
                );
                newPayments.add(p);
            }

            insert newPayments;
            return newPayments;
        } catch (Exception e) {
            Database.rollback(sp);
            if (e instanceof PaymentPlanException) {
                throw e;
            }
            throw new PaymentPlanException(e.getMessage());
        }
    }
}
