public class FamilyService {
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Map<Id, Id> filtered = new Map<Id, Id>();
        Set<Id> childIds = new Set<Id>();
        Set<Id> parentIds = new Set<Id>();

        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }
            filtered.put(childId, parentId);
            childIds.add(childId);
            parentIds.add(parentId);
        }

        if (filtered.isEmpty()) {
            return;
        }

        Set<Id> allIds = new Set<Id>();
        allIds.addAll(childIds);
        allIds.addAll(parentIds);

        Set<String> existingKeys = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :allIds
              AND npe4__RelatedContact__c IN :allIds
        ]) {
            Id c = rel.npe4__Contact__c;
            Id r = rel.npe4__RelatedContact__c;
            String key = String.valueOf(c) < String.valueOf(r)
                ? String.valueOf(c) + ':' + String.valueOf(r)
                : String.valueOf(r) + ':' + String.valueOf(c);
            existingKeys.add(key);
        }

        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        Set<String> seen = new Set<String>();

        for (Id childId : filtered.keySet()) {
            Id parentId = filtered.get(childId);
            String key = String.valueOf(childId) < String.valueOf(parentId)
                ? String.valueOf(childId) + ':' + String.valueOf(parentId)
                : String.valueOf(parentId) + ':' + String.valueOf(childId);

            if (existingKeys.contains(key) || seen.contains(key)) {
                continue;
            }
            seen.add(key);

            toInsert.add(new npe4__Relationship__c(
                npe4__Contact__c = childId,
                npe4__RelatedContact__c = parentId,
                npe4__Type__c = 'Parent',
                npe4__Status__c = 'Current'
            ));
        }

        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }
}
