public class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {
    public override npsp.TDTM_Runnable.DmlWrapper run(
        List<SObject> newList,
        List<SObject> oldList,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.TDTM_Runnable.DmlWrapper dw = new npsp.TDTM_Runnable.DmlWrapper();

        if (triggerAction != npsp.TDTM_Runnable.Action.AfterInsert &&
            triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate) {
            return dw;
        }

        List<Opportunity> newOpps = (List<Opportunity>) newList;
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(newOpps);
        Set<Id> candidateIds = new Set<Id>();

        if (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert) {
            for (Opportunity opp : newOpps) {
                if (isQualified(opp)) {
                    candidateIds.add(opp.Id);
                }
            }
        } else if (triggerAction == npsp.TDTM_Runnable.Action.AfterUpdate) {
            List<Opportunity> oldOpps = (List<Opportunity>) oldList;
            for (Integer i = 0; i < newOpps.size(); i++) {
                Opportunity newOpp = newOpps[i];
                Opportunity oldOpp = oldOpps[i];
                if (isQualified(newOpp) && !isQualified(oldOpp)) {
                    candidateIds.add(newOpp.Id);
                }
            }
        }

        if (candidateIds.isEmpty()) {
            return dw;
        }

        Set<Id> alreadyHasTask = new Set<Id>();
        for (Task t : [
            SELECT WhatId
            FROM Task
            WHERE WhatId IN :candidateIds
            AND Subject = 'Major gift thank-you call'
        ]) {
            alreadyHasTask.add(t.WhatId);
        }

        List<Task> tasksToInsert = new List<Task>();
        for (Id oppId : candidateIds) {
            if (alreadyHasTask.contains(oppId)) {
                continue;
            }
            Opportunity opp = oppMap.get(oppId);
            if (opp == null || opp.CloseDate == null) {
                continue;
            }
            Task t = new Task(
                Subject = 'Major gift thank-you call',
                Priority = 'High',
                Status = 'Not Started',
                WhatId = oppId,
                WhoId = opp.npsp__Primary_Contact__c,
                OwnerId = opp.OwnerId,
                ActivityDate = opp.CloseDate.addDays(3)
            );
            tasksToInsert.add(t);
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }

        return dw;
    }

    private static Boolean isQualified(Opportunity opp) {
        if (opp == null) {
            return false;
        }
        return opp.StageName == 'Closed Won' &&
               opp.Amount != null &&
               opp.Amount >= 5000 &&
               opp.CloseDate != null;
    }
}
