public with sharing class RecordAccessService {
    private static final Integer BATCH_SIZE = 200;

    public static Set<Id> editableIds(Set<Id> recordIds) {
        if (recordIds == null || recordIds.isEmpty()) {
            return new Set<Id>();
        }

        Set<Id> editable = new Set<Id>();
        List<Id> ids = new List<Id>(recordIds);

        for (Integer start = 0; start < ids.size(); start += BATCH_SIZE) {
            Integer end = Math.min(start + BATCH_SIZE, ids.size());
            Set<Id> batch = new Set<Id>();
            for (Integer i = start; i < end; i++) {
                batch.add(ids[i]);
            }

            for (UserRecordAccess ura : [
                SELECT RecordId
                FROM UserRecordAccess
                WHERE RecordId IN :batch
                AND UserId = :UserInfo.getUserId()
                AND HasEditAccess = true
            ]) {
                editable.add(ura.RecordId);
            }
        }

        return editable;
    }
}
