public class AccountOwnershipService {
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty() || newOwnerId == null) {
            return;
        }

        // Bypass all Account trigger actions for the Account update only
        TriggerBase.bypass(Schema.SObjectType.Account);
        try {
            List<Account> accountsToUpdate = new List<Account>();
            for (Id accId : accountIds) {
                accountsToUpdate.add(new Account(Id = accId, OwnerId = newOwnerId));
            }
            update accountsToUpdate;

            List<Contact> contactsToUpdate = new List<Contact>();
            for (Contact c : [SELECT Id FROM Contact WHERE AccountId IN :accountIds]) {
                contactsToUpdate.add(new Contact(Id = c.Id, OwnerId = newOwnerId));
            }
            if (!contactsToUpdate.isEmpty()) {
                update contactsToUpdate;
            }
        } finally {
            // Ensure Account automation is restored for the rest of the transaction
            TriggerBase.clearBypass(Schema.SObjectType.Account);
        }
    }
}
