public class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {
    private static final String ERROR_MSG = 'Another contact on this account already uses this email address.';

    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> newContacts = (List<Contact>) triggerNew;
        Set<Id> accountIds = new Set<Id>();
        for (Contact c : newContacts) {
            if (c.AccountId != null && String.isNotBlank(c.Email)) {
                accountIds.add(c.AccountId);
            }
        }

        Map<Id, Set<String>> accountToEmails = new Map<Id, Set<String>>();
        if (!accountIds.isEmpty()) {
            for (Contact c : [SELECT AccountId, Email FROM Contact WHERE AccountId IN :accountIds AND Email != null]) {
                String emailLower = c.Email.toLowerCase();
                Set<String> setEmails = accountToEmails.get(c.AccountId);
                if (setEmails == null) {
                    setEmails = new Set<String>();
                    accountToEmails.put(c.AccountId, setEmails);
                }
                setEmails.add(emailLower);
            }
        }

        for (Contact c : newContacts) {
            if (c.AccountId == null || String.isBlank(c.Email)) {
                continue;
            }
            String emailLower = c.Email.toLowerCase();
            Set<String> setEmails = accountToEmails.get(c.AccountId);
            if (setEmails == null) {
                setEmails = new Set<String>();
                accountToEmails.put(c.AccountId, setEmails);
            }
            if (setEmails.contains(emailLower)) {
                c.addError(ERROR_MSG);
            } else {
                setEmails.add(emailLower);
            }
        }
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> newContacts = (List<Contact>) triggerNew;
        List<Contact> oldContacts = (List<Contact>) triggerOld;

        Set<Id> accountIds = new Set<Id>();
        Set<Id> contactIdsToCheck = new Set<Id>();

        for (Integer i = 0; i < newContacts.size(); i++) {
            Contact newC = newContacts[i];
            Contact oldC = oldContacts[i];
            Boolean emailChanged = newC.Email != oldC.Email;
            Boolean accountChanged = newC.AccountId != oldC.AccountId;
            if (emailChanged || accountChanged) {
                if (newC.AccountId != null && String.isNotBlank(newC.Email)) {
                    accountIds.add(newC.AccountId);
                    contactIdsToCheck.add(newC.Id);
                }
            }
        }

        Map<Id, Set<String>> accountToEmails = new Map<Id, Set<String>>();
        if (!accountIds.isEmpty()) {
            List<Contact> existing;
            if (!contactIdsToCheck.isEmpty()) {
                existing = [
                    SELECT AccountId, Email 
                    FROM Contact 
                    WHERE AccountId IN :accountIds 
                    AND Id NOT IN :contactIdsToCheck 
                    AND Email != null
                ];
            } else {
                existing = [
                    SELECT AccountId, Email 
                    FROM Contact 
                    WHERE AccountId IN :accountIds 
                    AND Email != null
                ];
            }
            for (Contact c : existing) {
                String emailLower = c.Email.toLowerCase();
                Set<String> setEmails = accountToEmails.get(c.AccountId);
                if (setEmails == null) {
                    setEmails = new Set<String>();
                    accountToEmails.put(c.AccountId, setEmails);
                }
                setEmails.add(emailLower);
            }
        }

        for (Integer i = 0; i < newContacts.size(); i++) {
            Contact newC = newContacts[i];
            Contact oldC = oldContacts[i];
            Boolean emailChanged = newC.Email != oldC.Email;
            Boolean accountChanged = newC.AccountId != oldC.AccountId;
            Boolean needsCheck = emailChanged || accountChanged;
            if (!needsCheck) continue;
            if (newC.AccountId == null || String.isBlank(newC.Email)) {
                continue;
            }
            String emailLower = newC.Email.toLowerCase();
            Set<String> setEmails = accountToEmails.get(newC.AccountId);
            if (setEmails == null) {
                setEmails = new Set<String>();
                accountToEmails.put(newC.AccountId, setEmails);
            }
            if (setEmails.contains(emailLower)) {
                newC.addError(ERROR_MSG);
            } else {
                setEmails.add(emailLower);
            }
        }
    }
}
